'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var main = require( './../lib' );
var pure = require( './../lib/main.js' );
var canUseNative = require( './../lib/can_use_native.js' );
var common = require( './common.js' );


// TESTS //

tape('rank-only empty output and tolerance validation precedence', function test(t) {
	var rank;
	var fs = [
		main,
		pure
	];
	var i;
	for (i = 0; (i < fs.length); i++) {
		rank = new Int32Array([
			17,
			18,
			19
		]);
		t.strictEqual(fs[i].ndarray('upper', 0, null, NaN, null, undefined, null, undefined, null, rank, 1, -1, null, null, null), 0, 'empty success');
		t.deepEqual(common.snapshot(rank, true), [
			17,
			0,
			19
		], 'only active rank');
		t.throws(function call() { // eslint-disable-line no-loop-func
			fs[i]('row-major', 'upper', 0, null, 0, null, null, NaN, null);
		}, RangeError, 'nonfinite TOL before LDA/buffers');

		// eslint-disable-line no-loop-func
		t.throws(function call() { // eslint-disable-line no-loop-func
			fs[i]('row-major', 'upper', 0, null, 0, null, null, undefined, null);
		}, TypeError, 'required primitive TOL');

		// eslint-disable-line no-loop-func
		t.throws(function call() { // eslint-disable-line no-loop-func
			fs[i].ndarray('upper', 2147483648, null, 1, 1, 0, null, 1, 0, null, 0, -1, null, 1, 0);
		}, RangeError, 'dimension before buffers');	// eslint-disable-line no-loop-func
	}
	t.end();
});
tape('invalid active views and aliases leave all outputs untouched', function test(t) {
	var before;
	var a = new Float64Array([
		4,
		0,
		0,
		9
	]);
	var p = new Int32Array([
		-3,
		-4
	]);
	var r = new Int32Array([7]);
	var w = new Float64Array([
		11,
		12,
		13,
		14
	]);
	before = [
		common.snapshot(a, false),
		common.snapshot(p, true),
		common.snapshot(r, true),
		common.snapshot(w, false)
	];
	t.throws(function call() { // eslint-disable-line no-loop-func
		main.ndarray('upper', 2, a, 1, 1, 0, p, 1, 0, r, 0, -1, w, 1, 0);
	}, RangeError, 'matrix collision');
	t.throws(function call() { // eslint-disable-line no-loop-func
		main.ndarray('upper', 2, a, 2, 1, 0, p, 0, 0, r, 0, -1, w, 1, 0);
	}, RangeError, 'pivot broadcast');
	t.throws(function call() { // eslint-disable-line no-loop-func
		main.ndarray('upper', 2, a, 2, 1, 0, p, 1, 0, r, 0, -1, w, 0, 0);
	}, RangeError, 'scratch broadcast');
	t.throws(function call() { // eslint-disable-line no-loop-func
		main('row-major', 'upper', 2, a, 2, p, r, -1, a);
	}, RangeError, 'matrix/scratch overlap');
	t.throws(function call() { // eslint-disable-line no-loop-func
		main('row-major', 'upper', 2, a, 2, p, p, -1, w);
	}, RangeError, 'pivot/rank overlap');
	t.deepEqual([
		common.snapshot(a, false),
		common.snapshot(p, true),
		common.snapshot(r, true),
		common.snapshot(w, false)
	], before, 'no writes after invalid calls');
	t.end();
});
tape('first pivot precedes tolerance cutoff and INFO1 still produces full permutation', function test(t) {
	var a = new Float64Array([4]);
	var p = new Int32Array([-1]);
	var r = new Int32Array([-1]);
	var w = new Float64Array(2);
	t.strictEqual(main('row-major', 'lower', 1, a, 1, p, r, 100, w), 0, 'initial positive pivot retained');
	t.strictEqual(r[0], 1, 'full rank despite high TOL');
	t.strictEqual(a[0], 2, 'square root');
	a = new Float64Array([
		0,
		2,
		2,
		0
	]);
	p = new Int32Array([
		-8,
		-9
	]);
	r[0] = -9;
	w = new Float64Array([
		1,
		2,
		3,
		4
	]);
	t.strictEqual(main(101, 122, 2, a, 2, p, r, -1, w), 1, 'nonpositive initial maximum');
	t.deepEqual(common.snapshot(p, true), [
		1,
		2
	], 'all permutation slots produced');
	t.strictEqual(r[0], 0, 'rank zero');
	t.deepEqual(common.snapshot(w, false), [
		common.bits(1),
		common.bits(2),
		common.bits(3),
		common.bits(4)
	], 'scratch untouched before positive pivot');
	t.end();
});
tape('native eligibility includes corner sums and helper post-steps', function test(t) {
	t.strictEqual(canUseNative([
		121,
		2,
		null,
		1500000000,
		700000000,
		0,
		null,
		1,
		0,
		null,
		0,
		-1,
		null,
		1,
		0
	]), false, 'summed corner exceeds width');
	t.strictEqual(canUseNative([
		121,
		1,
		null,
		2147483648,
		0,
		0,
		null,
		0,
		0,
		null,
		0,
		-1,
		null,
		1,
		0
	]), false, 'wide unused metadata falls back');
	t.strictEqual(canUseNative([
		121,
		0,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		null,
		2147483648,
		-1,
		null,
		null,
		null
	]), false, 'wide empty rank offset falls back');
	t.end();
});
